/**
 * Guardrails extension — Pi's equivalent of the guard.py PreToolUse hook used by the other
 * tools in this repo (../../_shared/guardrails/guardrails.json). Pi has no declarative
 * permission-rule file: the documented mechanism for gating tool calls is a `tool_call`
 * extension handler (see https://pi.dev/docs/latest/extensions, "Tool Events"), so this
 * file is hand-ported from the same rule set rather than generated by _shared/build.py.
 *
 * - `bash` / `powershell` calls: event.input.command is matched against BLOCKED_COMMANDS.
 *   A rule with no `severity` is a hard block; `severity: "ask"` confirms via ctx.ui.confirm
 *   (falls back to a hard block when there is no UI, e.g. a headless/CI run).
 * - `write` / `edit` calls: event.input.path (confirmed field name — see
 *   github.com/earendil-works/pi examples/extensions/protected-paths.ts) is matched against
 *   PROTECTED_PATH_PATTERNS.
 *
 * Install: this file is auto-discovered from ~/.pi/agent/extensions/*.ts (see configuration.md).
 * Keep the rule data below in sync with _shared/guardrails/guardrails.json by hand if that
 * file changes — there is no shared build step wiring Pi into _shared/build.py.
 */

import type { ExtensionAPI } from "@earendil-works/pi-coding-agent";

interface CommandRule {
  id: string;
  pattern: RegExp;
  reason: string;
  severity?: "ask";
}

// Ported verbatim (regex semantics) from _shared/guardrails/guardrails.json `blocked_commands`.
// Python `re` patterns here translate directly to JS `RegExp` with the `i` flag.
const BLOCKED_COMMANDS: CommandRule[] = [
  {
    id: "rm-root",
    pattern:
      /\brm\s+(-[a-z]*r[a-z]*f[a-z]*|-[a-z]*f[a-z]*r[a-z]*|--recursive\s+--force|--force\s+--recursive)\s+(\/|\/\*|~|~\/|~\/\*|\$HOME\/?|\$HOME\/\*)(\s|$)/i,
    reason: "Recursive delete of filesystem root or home directory",
  },
  { id: "sudo-rm", pattern: /\bsudo\s+rm\b/i, reason: "Privileged deletion" },
  { id: "srm", pattern: /(^|\s)srm\s/i, reason: "Irreversible secure-delete" },
  {
    id: "find-delete-root",
    pattern: /\bfind\s+\/\S*\s.*(-delete|-exec\s+rm)/i,
    reason: "Mass deletion from filesystem root",
  },
  {
    id: "dd-device",
    pattern: /\bdd\b.*\bof=\/dev\//i,
    reason: "Raw write to a block device",
  },
  {
    id: "redirect-device",
    pattern: />\s*\/dev\/(disk|sd|nvme|hd|xvd)/i,
    reason: "Raw write to a block device",
  },
  {
    id: "mkfs",
    pattern: /\b(mkfs(\.\w+)?|newfs_\w+|wipefs|gpt\s+destroy)\b/i,
    reason: "Filesystem/partition destruction",
  },
  {
    id: "diskutil",
    pattern:
      /\bdiskutil\s+(erase\w*|apfs\s+deletecontainer|partitiondisk|zerodisk|randomdisk|securerase)/i,
    reason: "macOS disk erase/partition",
  },
  {
    id: "csrutil",
    pattern: /\bcsrutil\b/i,
    reason: "System Integrity Protection tampering",
  },
  {
    id: "chmod-root",
    pattern: /\bchmod\s+-R\s+(777|000|a\+rwx)\s+\/(\s|$|\*)/i,
    reason: "Recursive permission change on /",
  },
  {
    id: "chown-root",
    pattern: /\bchown\s+-R\s+\S+\s+\/(\s|$)/i,
    reason: "Recursive ownership change on /",
  },
  {
    id: "brew-purge",
    pattern:
      /\bbrew\s+(remove|uninstall)\s+.*(--force\s+--ignore-dependencies|--zap|\$\(brew\s+list)/i,
    reason: "Unsafe Homebrew purge",
  },
  {
    id: "win-disk",
    pattern: /\b(format-volume|clear-disk|initialize-disk|format\s+[a-z]:)/i,
    reason: "Windows disk format/wipe",
  },
  {
    id: "win-rm-root",
    pattern:
      /remove-item\b.*-recurse.*\s[a-z]:\\?(\s|$)|remove-item\b.*\s[a-z]:\\?\s.*-recurse/i,
    reason: "Recursive delete of a Windows drive root",
  },
  {
    id: "pipe-to-shell",
    pattern:
      /(curl|wget|iwr|invoke-webrequest|irm|invoke-restmethod)\b[^|]*\|\s*(sudo\s+)?(sh|bash|zsh|pwsh|powershell|iex|invoke-expression|python3?)\b/i,
    reason: "Remote code piped into an interpreter",
  },
  {
    id: "iex",
    pattern: /\b(iex|invoke-expression)\b/i,
    reason: "Invoke-Expression on dynamic content",
  },
  {
    id: "git-force-push",
    pattern:
      /\bgit(\s+(-C\s+\S+|-c\s+\S+|--[\w-]+(=\S+)?))*\s+push\b.*(\s--force(\s|$|=)|\s-f(\s|$)|\s--force-with-lease|\s--mirror|\s--delete|\s\+\S+)/i,
    reason: "Force push / remote rewrite",
  },
  {
    id: "git-push",
    pattern: /\bgit(\s+(-C\s+\S+|-c\s+\S+|--[\w-]+(=\S+)?))*\s+push\b/i,
    reason: "Pushes are done manually by Murpheux",
    severity: "ask",
  },
  {
    id: "git-reset-hard",
    pattern:
      /\bgit(\s+(-C\s+\S+|-c\s+\S+|--[\w-]+(=\S+)?))*\s+(reset\s+--hard|clean\s+-[a-z]*f)/i,
    reason: "Discards local work",
    severity: "ask",
  },
  {
    id: "tf-destroy",
    pattern: /\b(terraform|tofu|terragrunt)\s+(destroy|apply\s+.*-destroy)/i,
    reason: "Infrastructure destruction",
  },
  {
    id: "auto-approve",
    pattern: /-auto-approve\b/i,
    reason: "Unreviewed infrastructure change",
  },
  {
    id: "s3-destroy",
    pattern: /\baws\s+s3\s+(rb\s|rm\s.*--recursive)/i,
    reason: "S3 bucket/object mass deletion",
  },
  {
    id: "k8s-delete-ns",
    pattern: /\bkubectl\s+delete\s+(namespace|ns)\b/i,
    reason: "Namespace deletion",
  },
  {
    id: "docker-prune-all",
    pattern:
      /\bdocker\s+system\s+prune\s+.*-a.*--volumes|\bdocker\s+system\s+prune\s+.*--volumes.*-a/i,
    reason: "Deletes all images and volumes",
  },
  {
    id: "docker-stack-rm",
    pattern: /\bdocker\s+(--context[= ]\S+\s+)?(stack|service)\s+rm\b/i,
    reason: "Removes Swarm stacks/services",
    severity: "ask",
  },
  {
    id: "sql-destructive",
    pattern: /\b(drop\s+(database|table|schema)|truncate\s+table)\b/i,
    reason: "Destructive SQL",
    severity: "ask",
  },
  {
    id: "op-read-secret",
    pattern: /\bop\s+(read|item\s+get|document\s+get|inject)\b/i,
    reason: "Prints 1Password secrets into model context",
  },
  {
    id: "gh-token",
    pattern: /\bgh\s+auth\s+token\b/i,
    reason: "Prints GitHub token",
  },
  {
    id: "aws-creds",
    pattern: /\baws\s+configure\s+(get|export-credentials)\b/i,
    reason: "Prints AWS credentials",
  },
  {
    id: "env-dump",
    pattern:
      /(^|[;&|]\s*)(printenv|env|set|export\s+-p|get-childitem\s+env:|gci\s+env:|dir\s+env:)\s*($|[;&|])/i,
    reason: "Dumps environment secrets",
  },
  {
    id: "dotenv-access",
    pattern:
      /(^|[\s'"=/])\.env(\.(?!example\b|sample\b|template\b)[\w.-]+)?($|[\s'";|&)])/i,
    reason: "Reads or writes a .env secrets file",
  },
  {
    id: "private-key-cat",
    pattern:
      /\b(cat|less|more|head|tail|type|get-content|gc|bat|xxd|base64)\b.*(id_rsa|id_ed25519|id_ecdsa|\.pem\b|\.key\b|\.aws\/credentials|\.kube\/config|\.docker\/config\.json|\.tfstate)/i,
    reason: "Reads private keys or credential files",
  },
  {
    id: "rg-no-ignore",
    pattern: /\brg\b.*(\s-uu|--no-ignore)/i,
    reason: "Search that bypasses .gitignore (exposes secrets)",
  },
];

// Ported from `protected_paths.read_and_write` (write/edit only here — Pi's `read` tool stays
// unfiltered by default; override it per tool-override.ts if you also want read-side blocking).
const PROTECTED_PATH_PATTERNS: RegExp[] = [
  /(^|\/)\.env$/,
  /(^|\/)\.env\.(?!example$|sample$|template$)[^/]+$/,
  /(^|\/)\.ssh\/(?!config$|known_hosts$|[^/]+\.pub$)[^/]+$/,
  /(^|\/)\.aws\/credentials$/,
  /(^|\/)\.gnupg\//,
  /(^|\/)\.config\/op\//,
  /(^|\/)\.kube\/config/,
  /(^|\/)\.docker\/config\.json$/,
  /\.tfstate(\.backup)?$/,
  /\.(key|pfx|p12|kdbx)$/,
  /(^|\/)(id_rsa|id_ed25519|id_ecdsa)$/,
  /(^|\/)\.pi\/agent\/auth\.json$/,
  /(^|\/)\.pi\/agent\/mcp-auth\.json$/,
  /(^|\/)\.git\//,
  /(^|\/)\.aws\//,
  /(^|\/)\.ssh\//,
];

function splitCommand(command: string): string[] {
  return command
    .split(/;|&&|\|\||\n/)
    .map((part) => part.trim())
    .filter(Boolean);
}

export default function (pi: ExtensionAPI) {
  pi.on("tool_call", async (event, ctx) => {
    if (event.toolName === "bash" || event.toolName === "powershell") {
      const command = (event.input as { command: string }).command;
      const parts = [command, ...splitCommand(command)];
      for (const rule of BLOCKED_COMMANDS) {
        if (!parts.some((p) => rule.pattern.test(p))) continue;
        if (rule.severity === "ask") {
          if (ctx.hasUI) {
            const ok = await ctx.ui.confirm(
              "Guardrails",
              `${rule.reason}. Allow this command?\n\n${command}`,
            );
            if (ok) return undefined;
          }
          return {
            block: true,
            reason: `${rule.reason} (${rule.id}) — needs explicit approval`,
          };
        }
        return {
          block: true,
          reason: `${rule.reason} (${rule.id})`,
          terminate: false,
        };
      }
      return undefined;
    }

    if (event.toolName === "write" || event.toolName === "edit") {
      const path = (event.input as { path: string }).path;
      const hit = PROTECTED_PATH_PATTERNS.find((pattern) => pattern.test(path));
      if (hit) {
        if (ctx.hasUI) {
          ctx.ui.notify(
            `Blocked ${event.toolName} to protected path: ${path}`,
            "warning",
          );
        }
        return {
          block: true,
          reason: `"${path}" is a protected credential/secrets path`,
        };
      }
      return undefined;
    }

    return undefined;
  });
}
